		var data []byte
		mode := NonStrict
		if verbose {
			data = p.SerializeVerbose()
			mode = Strict
		} else {
			data = p.Serialize()
		}
		p1, err := target.Deserialize(data, mode)
		if err != nil {
			t.Fatalf("failed to deserialize program: %v\n%s", err, data)
		}
		if p1 == nil {
			t.Fatalf("deserialized nil program:\n%s", data)
		}
		var data1 []byte
		if verbose {
			data1 = p1.SerializeVerbose()
